package kernel

import (
	"bufio"
	"context"
	"io"
	"log/slog"
	"maps"
	"os"
	"sort"
	"strings"
	"testing"

	"github.com/falkcorp/mediacore/config"
)

// The core half of F3-07's TestRenameTable_EveryKeyRegistered (05-config
// section 1.12.3, IMPL-1). The app's rename table projects onto core as
// testdata/rename_core_targets.golden (generated by ABO's internal/books/cutover,
// which fails when the table and the fixture differ): canonical core paths and
// verdicts only, no HEAD name (03 R1). These tests read it against coreSections(),
// which only this package can see, so core needs no test-support export of
// its registry (the kernel.CoreKeys export this replaces was kept in the
// deadcode baseline for the sake of one external test).

// renameContract is the fixture, parsed.
type renameContract struct {
	targets  []config.Path
	coined   []config.Path
	verdicts []struct {
		path   config.Path
		refuse bool
	}
}

func readRenameContract(t *testing.T) renameContract {
	t.Helper()
	f, err := os.Open("testdata/rename_core_targets.golden")
	if err != nil {
		t.Fatalf("read the rename-table contract fixture: %v", err)
	}
	defer f.Close()
	var c renameContract
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		fields := strings.Fields(line)
		switch {
		case len(fields) == 2 && fields[0] == "target":
			c.targets = append(c.targets, config.Path(fields[1]))
		case len(fields) == 2 && fields[0] == "coined":
			c.coined = append(c.coined, config.Path(fields[1]))
		case len(fields) == 3 && fields[0] == "verdict" && (fields[2] == "refuse" || fields[2] == "warn"):
			c.verdicts = append(c.verdicts, struct {
				path   config.Path
				refuse bool
			}{config.Path(fields[1]), fields[2] == "refuse"})
		default:
			t.Fatalf("unreadable line in the contract fixture: %q", line)
		}
	}
	if err := sc.Err(); err != nil {
		t.Fatal(err)
	}
	if len(c.targets) == 0 || len(c.verdicts) == 0 {
		t.Fatalf("the contract fixture names %d targets and %d verdicts: the tests would check nothing", len(c.targets), len(c.verdicts))
	}
	return c
}

// coreKeyStates is every key core's sections declare, as a store over them
// reports it: no operator layer and no database layer, so the same on every
// host.
func coreKeyStates(t *testing.T) map[config.Path]config.KeyState {
	t.Helper()
	ctx := context.Background()
	st, err := config.NewStore(config.Options{AppID: "corekeys", Environ: []string{}, Logger: slog.New(slog.NewTextHandler(io.Discard, nil))})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = st.Close(ctx) })
	if _, err := config.RegisterSections(st.Registry(), coreSections()...); err != nil {
		t.Fatal(err)
	}
	if err := st.Load(ctx); err != nil {
		t.Fatal(err)
	}
	return maps.Collect(st.Keys())
}

// dynamicCoreRows are the contract targets whose canonical path is not a
// registered key or a container with keys below it: the members of a map key
// (core.tasks.windows.<name>.{enabled,start,end}), matched by prefix against
// the registry. Each entry is a reviewed prefix, and the test requires a
// registered key at or under it, so a typo here, or a section dropped from
// core, fails. An entry no row needs is dead and does not belong
// (core.updater.* is an ordinary container, found by keys below it).
var dynamicCoreRows = []config.Path{
	"core.tasks.windows",
}

// under reports a registered key at or below prefix.
func under(keys map[config.Path]config.KeyState, prefix config.Path) bool {
	for k := range keys {
		if k == prefix || strings.HasPrefix(string(k), string(prefix)+".") {
			return true
		}
	}
	return false
}

// contractRegistered reports whether canonical path p is served by core's
// registry: itself a key, a container with keys below it, or a reviewed
// dynamic row with keys at or under its prefix.
func contractRegistered(keys map[config.Path]config.KeyState, p config.Path) bool {
	if _, ok := keys[p]; ok || under(keys, p) {
		return true
	}
	if _, ok := keys["core.auth.oidc.providers"]; ok && oidcEntrySecret(p) {
		return true
	}
	for _, d := range dynamicCoreRows {
		if (p == d || strings.HasPrefix(string(p), string(d)+".")) && under(keys, d) {
			return true
		}
	}
	return false
}

// oidcEntrySecret matches core.auth.oidc.<id>.client_secret, the secret of one
// provider entry of the list key core.auth.oidc.providers (secret:"bind"): the
// name exists per entry at runtime, so only its list key is registered.
func oidcEntrySecret(p config.Path) bool {
	rest, ok := strings.CutPrefix(string(p), "core.auth.oidc.")
	id, leaf, cut := strings.Cut(rest, ".")
	return ok && cut && id != "" && leaf == "client_secret"
}

// TestRenameTable_CoreKeysRegistered: every core canonical path a key, secret,
// entry or fold target of the app's rename table names is registered in core's
// own registry, so M2 never stages into a path core does not know.
func TestRenameTable_CoreKeysRegistered(t *testing.T) {
	keys, c := coreKeyStates(t), readRenameContract(t)
	var missing []string
	for _, p := range c.targets {
		if !contractRegistered(keys, p) {
			missing = append(missing, string(p))
		}
	}
	sort.Strings(missing)
	for _, m := range missing {
		t.Errorf("core path %s is a rename-table target but no core section declares it", m)
	}
}

// TestRenameTable_CoreCoinedRowsDeclared: every path the spec coins and no
// owner table declared (seams.d/F2-09.md "Not declared") is a key core
// declares, so dropping a section fails here. The two rows named by their
// HEAD names are pinned by the app's TestRenameTable_CoinedCoreRowsMarked.
func TestRenameTable_CoreCoinedRowsDeclared(t *testing.T) {
	keys, c := coreKeyStates(t), readRenameContract(t)
	want := map[config.Path]bool{"core.ai.journal_retention": false, "core.http.public_base_url": false}
	for _, p := range c.coined {
		if _, ok := want[p]; ok {
			want[p] = true
		}
		if !contractRegistered(keys, p) {
			t.Errorf("coined path %s is not declared by core", p)
		}
	}
	for p, seen := range want {
		if !seen {
			t.Errorf("the fixture does not coin %s", p)
		}
		if _, ok := keys[p]; !ok {
			t.Errorf("%s is not a core key", p)
		}
	}
}

// TestRenameTable_RefuseVerdictsMatchConfig (F3-06's seam item, owner F3-07):
// a retired name whose canonical path is a core key refuses when config itself
// would refuse it, a ProtectAdmin-or-higher or secret key anywhere under the
// path, and warns otherwise. The fixture's verdicts come from the table's own
// admin column; this compares them with the registry's.
func TestRenameTable_RefuseVerdictsMatchConfig(t *testing.T) {
	keys, c := coreKeyStates(t), readRenameContract(t)
	compared := 0
	for _, v := range c.verdicts {
		var below []config.KeyState
		for k, ks := range keys {
			if k == v.path || strings.HasPrefix(string(k), string(v.path)+".") {
				below = append(below, ks)
			}
		}
		if len(below) == 0 {
			continue // the registered-path test reports it
		}
		wantRefuse := false
		for _, ks := range below {
			if ks.Protection >= config.ProtectAdmin || ks.Secret != nil {
				wantRefuse = true
			}
		}
		compared++
		if v.refuse != wantRefuse {
			t.Errorf("retired name of %s: the table's verdict refuse=%v, config refuses=%v", v.path, v.refuse, wantRefuse)
		}
	}
	if compared == 0 {
		t.Fatal("no retired name of a core key was compared")
	}
}
